    let response = client
        .get(discovery)
        .basic_auth("x-access-token", Some("fake-github-token"))
        .send()
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);
    assert_eq!(
        response.text().await.unwrap(),
        advertisement("git-receive-pack")
    );
    assert_eq!(state.view().requests[0].status, Some(200));

    // A real Git process retries the server challenge using the same managed
    // include installed in guests. Only dummy credentials exist, and the
    // connector cannot go online.
    let mut git = tokio::process::Command::new("git");
    git.env_clear();
    // Exercise the installed Windows backend and the guest setup fix: Schannel
    // keeps verification enabled but is explicitly allowed to honor the PEM.
    if cfg!(windows) {
        git.args(["-c", "http.sslBackend=schannel"])
            .env("GIT_CONFIG_COUNT", "2")
            .env("GIT_CONFIG_KEY_0", "http.schannelUseSSLCAInfo")
            .env("GIT_CONFIG_VALUE_0", "true")
            .env("GIT_CONFIG_KEY_1", "include.path")
            .env("GIT_CONFIG_VALUE_1", &helper_config);
    } else {
        git.env("GIT_CONFIG_COUNT", "1")
            .env("GIT_CONFIG_KEY_0", "include.path")
            .env("GIT_CONFIG_VALUE_0", &helper_config);
    }
    for key in [
        "PATH",
        "SystemRoot",
        "WINDIR",
        "SystemDrive",
        "COMSPEC",
        "TEMP",
        "TMP",
    ] {
        if let Some(value) = std::env::var_os(key) {
            git.env(key, value);
        }
    }
    git.current_dir(&dir.0)
        .env("HOME", &dir.0)
        .env("USERPROFILE", &dir.0)
        .env("XDG_CONFIG_HOME", &dir.0)
        .env("APPDATA", &dir.0)
        .env("LOCALAPPDATA", &dir.0)
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env("GIT_CONFIG_GLOBAL", &config)
        .env("GIT_TERMINAL_PROMPT", "0")
        .env("GIT_SSL_CAINFO", &ca)
        .env("GITHUB_TOKEN", "fake-github-token")
        .kill_on_drop(true)
        .args([
            "-c",
            "http.sslVerify=true",
            "-c",
            "protocol.version=0",
            "-c",
            "http.followRedirects=false",
            "-c",
            &format!("http.proxy=http://{address}"),
            "ls-remote",
            "https://github.com/cline/cline.git",
        ]);
    let before = seen.lock().unwrap().len();
    let output = tokio::time::timeout(Duration::from_secs(15), git.output())
        .await
        .unwrap()
        .expect("Git must be installed for Basic auth interoperability test");
    assert!(
        output.status.success(),
        "git ls-remote failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(String::from_utf8_lossy(&output.stdout).contains("refs/heads/main"));
    let observed = seen.lock().unwrap()[before..].to_vec();
    assert!(
        observed.contains(&None),
        "Git must first receive an origin challenge"
    );
    assert!(
        observed.iter().any(Option::is_some),
        "Git must retry with Basic credentials"
    );
    let expected = format!(
        "Basic {}",
        STANDARD.encode(b"x-access-token:[REDACTED]")
    );
    assert!(observed.iter().flatten().all(|value| value == &expected));

    // Git LFS is a separate process, but inherits the managed include through
    // GIT_CONFIG_* environment entries. The first empty helper clears inherited
    // helpers for GitHub; after the fixture's LFS-Authenticate 401, the second
    // returns only the fake token and Friendzone substitutes it.
    let repo = dir.0.join("lfs-repository");
    std::fs::create_dir_all(&repo).unwrap();
    for args in [
        vec!["init", "--quiet"],
        vec!["config", "user.name", "Fixture"],
        vec!["config", "user.email", "fixture@example.invalid"],
        vec![
            "remote",
            "add",
            "origin",
            "https://github.com/cline/cline.git",
        ],
    ] {
        assert!(
            std::process::Command::new("git")
                .current_dir(&repo)
                .args(args)
                .status()
                .unwrap()
                .success()
        );
    }
    std::fs::write(
        repo.join("asset.bin"),
        format!(
            "version https://git-lfs.github.com/spec/v1\noid sha256:{lfs_oid}\nsize {}\n",
            lfs_object.len()
        ),
    )
    .unwrap();
    std::fs::write(
        repo.join(".gitattributes"),
        "asset.bin filter=lfs diff=lfs merge=lfs -text\n",
    )
    .unwrap();
    assert!(
        std::process::Command::new("git")
            .current_dir(&repo)
            .args(["add", ".gitattributes", "asset.bin"])
            .status()
            .unwrap()
            .success()
    );
    assert!(
        std::process::Command::new("git")
            .current_dir(&repo)
            .args(["commit", "--quiet", "-m", "LFS pointer"])
            .status()
            .unwrap()
            .success()
    );
    let mut lfs = tokio::process::Command::new("git");
    lfs.current_dir(&repo)
        .env("GITHUB_TOKEN", "fake-github-token")
        .env("HTTPS_PROXY", format!("http://{address}"))
        .env("HTTP_PROXY", format!("http://{address}"))
        .env("NO_PROXY", "")
        .env("GIT_SSL_CAINFO", &ca)
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env("GIT_CONFIG_GLOBAL", &config)
        .env("GIT_TERMINAL_PROMPT", "0")
        .kill_on_drop(true)
        .args(["lfs", "fetch", "origin", "HEAD"]);
    if cfg!(windows) {
        lfs.env("GIT_CONFIG_COUNT", "2")
            .env("GIT_CONFIG_KEY_0", "http.schannelUseSSLCAInfo")
            .env("GIT_CONFIG_VALUE_0", "true")
            .env("GIT_CONFIG_KEY_1", "include.path")
            .env("GIT_CONFIG_VALUE_1", &helper_config);
    } else {
        lfs.env("GIT_CONFIG_COUNT", "1")
            .env("GIT_CONFIG_KEY_0", "include.path")
            .env("GIT_CONFIG_VALUE_0", &helper_config);
    }
    let output = tokio::time::timeout(Duration::from_secs(20), lfs.output())
        .await
        .unwrap()
        .expect("Git LFS must be installed for interoperability test");
    assert!(
        output.status.success(),
        "git lfs fetch failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let downloaded = repo
        .join(".git/lfs/objects")
        .join(&lfs_oid[..2])
        .join(&lfs_oid[2..4])
        .join(&lfs_oid);
    assert_eq!(std::fs::read(downloaded).unwrap(), lfs_object);
    let lfs_auth = lfs_seen.lock().unwrap().clone();
    assert!(
        lfs_auth.contains(&None),
        "Git LFS must first receive a challenge"
    );
    assert!(lfs_auth.iter().any(Option::is_some));
    assert!(lfs_auth.iter().flatten().all(|value| value == &expected));

    let lfs_calls = lfs_auth.len();
    let blocked = client
        .post("https://github.com/cline/cline.git/info/lfs/objects/batch")
        .basic_auth("x-access-token", Some("fake-github-token"))
        .header("accept", "application/vnd.git-lfs+json")
        .header("content-type", "application/vnd.git-lfs+json")
        .body(format!(
            r#"{{"operation":"upload","transfers":["basic"],"objects":[{{"oid":"{lfs_oid}","size":{}}}]}}"#,
            lfs_object.len()
        ))
        .send()
        .await
        .unwrap();
    assert_eq!(blocked.status(), StatusCode::FORBIDDEN);
    assert!(blocked.text().await.unwrap().contains("Git LFS uploads"));
    assert_eq!(
        lfs_seen.lock().unwrap().len(),
        lfs_calls,
        "upload reached upstream"
    );
    assert!(state.reviews.summaries().is_empty());

    // Cargo's configured proxy takes precedence over generic proxy variables.
    // A local rejecting proxy makes that choice observable without going online.
    let other_proxy = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let other_address = other_proxy.local_addr().unwrap();
    let other_hits = Arc::new(AtomicUsize::new(0));
    let other_received = other_hits.clone();
    let _other_proxy = Task(tokio::spawn(async move {
        use tokio::io::AsyncWriteExt;
        loop {
            let (mut socket, _) = other_proxy.accept().await.unwrap();
            other_received.fetch_add(1, Ordering::SeqCst);
            let _ = socket
                .write_all(b"HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\n\r\n")
                .await;
        }
    }));
    let cargo_home = dir.0.join("cargo-home");
    std::fs::create_dir_all(&cargo_home).unwrap();
    std::fs::write(
        cargo_home.join("config.toml"),
        format!("[http]\nproxy = \"http://{other_address}\"\n"),
    )
    .unwrap();
    // Cargo's vendored libcurl uses Schannel on Windows. Its native CA setting
    // verifies the generated interception certificate. CARGO_HOME and both
    // proxies are isolated, so this cannot read user config or go online.
    let cargo_executable = std::env::var_os("FZ_TEST_CARGO")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            std::process::Command::new("rustup")
                .args(["which", "cargo"])
                .output()
                .ok()
                .filter(|output| output.status.success())
                .and_then(|output| String::from_utf8(output.stdout).ok())
                .map(|path| PathBuf::from(path.trim()))
                .unwrap_or_else(|| PathBuf::from("cargo"))
        });
    let mut cargo = tokio::process::Command::new(cargo_executable);
    cargo.env_clear();
    for key in [
        "PATH",
        "SystemRoot",
        "WINDIR",
        "SystemDrive",
        "COMSPEC",
        "TEMP",
        "TMP",
    ] {
        if let Some(value) = std::env::var_os(key) {
            cargo.env(key, value);
        }
    }
    cargo
        .current_dir(&dir.0)
        .env("HOME", &dir.0)
        .env("USERPROFILE", &dir.0)
        .env("CARGO_HOME", &cargo_home)
        .env("HTTP_PROXY", format!("http://{address}"))
        .env("HTTPS_PROXY", format!("http://{address}"))
        .env("NO_PROXY", "")
        .env("CARGO_HTTP_CAINFO", &ca)
        .env("CARGO_HTTP_CHECK_REVOKE", "false")
        .env("CARGO_HTTP_TIMEOUT", "10")
        .env("CARGO_NET_RETRY", "0")
        .kill_on_drop(true)
        .args(["search", "friendzone-cargo-ca-fixture", "--limit", "1"]);
    let output = tokio::time::timeout(Duration::from_secs(15), cargo.output())
        .await
        .unwrap()
        .expect("Cargo must be installed for proxy precedence test");
    assert!(!output.status.success());
    assert!(other_hits.load(Ordering::SeqCst) > 0);
    assert_eq!(cargo_hits.load(Ordering::SeqCst), 0);
    let rejected = other_hits.load(Ordering::SeqCst);
    cargo.env("CARGO_HTTP_PROXY", format!("http://{address}"));
    let output = tokio::time::timeout(Duration::from_secs(15), cargo.output())
        .await
        .unwrap()
        .expect("Cargo must be installed for CA interoperability test");
    assert!(
        output.status.success(),
        "cargo search failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(String::from_utf8_lossy(&output.stdout).contains("friendzone-cargo-ca-fixture"));
    assert_eq!(cargo_hits.load(Ordering::SeqCst), 1);
    assert_eq!(other_hits.load(Ordering::SeqCst), rejected);

    let before = seen.lock().unwrap().len();
    let blocked = client
        .post("https://github.com/cline/cline.git/git-receive-pack")
        .basic_auth("octocat", Some("fake-github-token"))
        .body("unreviewed pack")
        .send()
        .await
        .unwrap();
    assert_eq!(blocked.status(), StatusCode::FORBIDDEN);
    assert!(state.reviews.summaries().is_empty());
    assert_eq!(
        seen.lock().unwrap().len(),
        before,
        "write was not forwarded"
    );
    let blocked = client
        .get("https://wrong.example/info/refs?service=git-receive-pack")
        .basic_auth("octocat", Some("fake-github-token"))
        .send()
        .await
        .unwrap();
    assert_eq!(blocked.status(), StatusCode::FORBIDDEN);
    assert!(blocked.text().await.unwrap().contains("non-pinned host"));
    settings.remove_secret("github").unwrap();
    assert_eq!(
        client
            .get(discovery)
            .basic_auth("octocat", Some("fake-github-token"))
            .send()
            .await
            .unwrap()
            .status(),
        StatusCode::FORBIDDEN
    );
    assert_eq!(
        seen.lock().unwrap().len(),
        before,
        "missing secret was not forwarded"
    );
    let audit = serde_json::to_string(&state.view()).unwrap();
    assert!(!audit.contains("fixture-real-token"));
    assert!(!audit.contains(&STANDARD.encode(b"x-access-token:[REDACTED]")));
}

param([string]$BootstrapScript, [string]$MachineCertificateScript, [string]$TemporaryDirectory)
$ErrorActionPreference='Stop'
. ([scriptblock]::Create([IO.File]::ReadAllText($BootstrapScript).TrimStart([char]0xfeff)))
$payloadMatch=[regex]::Match([IO.File]::ReadAllText($BootstrapScript),'\$data=\[Text.Encoding\]::UTF8.GetString\(\[Convert\]::FromBase64String\(''([A-Za-z0-9+/=]+)''\)\)')
$data=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($payloadMatch.Groups[1].Value))|ConvertFrom-Json
$identity=ConvertTo-FzCertificateIdentity $data.ca
. ([scriptblock]::Create([IO.File]::ReadAllText($MachineCertificateScript).TrimStart([char]0xfeff)))
$script:allowMachine=$true;$script:rootWrites=0
$script:roots=@{CurrentUser=@{};LocalMachine=@{}}
function Assert-FzMachineCertificateAccess {if(-not$script:allowMachine){throw 'mock elevation required'}}
function Get-FzTrustedCertificate([string]$Thumbprint,[string]$StoreLocation='CurrentUser'){
    $stores=if($StoreLocation-eq'CurrentUser'){@('CurrentUser','LocalMachine')}else{@('LocalMachine')}
    foreach($store in $stores){if($script:roots[$store].ContainsKey($Thumbprint)){return @{present=$true;der=$script:roots[$store][$Thumbprint]}}}
    @{present=$false;der=$null}
}
function Add-FzTrustedCertificate([string]$Der,[string]$StoreLocation='CurrentUser'){
    $script:rootWrites++
    $certificate=New-Object Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList (,[Convert]::FromBase64String($Der))
    try{$script:roots[$StoreLocation][$certificate.Thumbprint.ToUpperInvariant()]=$Der}finally{$certificate.Dispose()}
}
function Remove-FzTrustedCertificate([string]$Thumbprint,[string]$ExpectedDer){
    if($script:roots.CurrentUser.ContainsKey($Thumbprint)-and$script:roots.CurrentUser[$Thumbprint]-cne$ExpectedDer){throw 'mock root mismatch'}
    $script:roots.CurrentUser.Remove($Thumbprint)
}
$machineOutput=Install-FzMachineCertificate $data.ca 6>&1|Out-String
if($script:rootWrites-ne 1-or$script:roots.CurrentUser.Count-ne 0-or$script:roots.LocalMachine[$identity.thumbprint]-cne$identity.der){throw 'machine bootstrap wrote the wrong trust store'}
$repeat=Install-FzMachineCertificate $data.ca 6>&1|Out-String
if($script:rootWrites-ne 1-or-not$repeat.Contains('already installed')){throw 'machine bootstrap rerun was not idempotent'}
$script:allowMachine=$false
try{Install-FzMachineCertificate $data.ca;throw 'expected elevation failure'}catch{if($_.Exception.Message-eq'expected elevation failure'){throw}}
$script:allowMachine=$true
try{Install-FzMachineCertificate 'invalid PEM';throw 'expected malformed CA failure'}catch{if($_.Exception.Message-eq'expected malformed CA failure'){throw}}
$script:roots.LocalMachine[$identity.thumbprint]='different bytes'
try{Install-FzMachineCertificate $data.ca;throw 'expected trust mismatch failure'}catch{if($_.Exception.Message-eq'expected trust mismatch failure'){throw}}
$script:roots.LocalMachine[$identity.thumbprint]=$identity.der
if($script:rootWrites-ne 1){throw 'machine bootstrap wrote during failed validation'}

# Every registry/trust operation stays in these adapters. File operations use
# generated scripts and real temporary profile files under both runtimes.
$script:user=@{};$script:internet=@{};$script:userWrites=0
