                ps_quote(&home.join("machine-and-profile").to_string_lossy()),
            );
            std::fs::create_dir_all(home.join("machine-and-profile")).unwrap();
            let output = std::process::Command::new(&executable)
                .args(["-NoProfile", "-NonInteractive", "-Command", &inline])
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "{runtime}: {}\n{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
            if let Some(artifacts) = std::env::var_os("FZ_PLUGIN_TEST_ARTIFACT_DIR") {
                let artifacts = std::path::PathBuf::from(artifacts);
                std::fs::create_dir_all(&artifacts).unwrap();
                // Use the bytes actually written by Invoke-FzConfigure, not source.
                std::fs::copy(
                    home.join("Guest space ' ü/.cline/plugins/friendzone.js"),
                    artifacts.join(format!("windows-{runtime}.js")),
                )
                .unwrap();
            }
        }
        std::fs::remove_dir_all(dir).unwrap();
    }
}

//! Cline account device-code OAuth. MCP server OAuth lives in mcp_oauth.

use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
};

use anyhow::{Context, Result};
use serde::Deserialize;

use crate::settings::Settings;

// ---------------------------------------------------------------------
// Cline account sign-in via the WorkOS device-code flow — the current
// method (the SDK defaults useWorkOSDeviceAuth to true; the legacy
// callback flow redirects into the editor extension, which we are not).
// Contract from cline/cline sdk/packages/core/src/auth/cline.ts:
//   device:   POST https://api.workos.com/user_management/authorize/device
//               form: client_id
//               -> {device_code, user_code, verification_uri,
//                   verification_uri_complete?, expires_in?, interval?}
//   poll:     POST https://api.workos.com/user_management/authenticate
//               form: grant_type=urn:ietf:params:oauth:grant-type:device_code,
//                     device_code, client_id
//               -> {access_token, refresh_token} | {"error":
//                  "authorization_pending" | "slow_down" | terminal}
//   register: POST {base}/api/v1/auth/register
//               json: {accessToken, refreshToken}
//   refresh:  POST {base}/api/v1/auth/refresh
//               json: {"refreshToken":..,"grantType":"refresh_token"}
// Cline responses: {"success":true,"data":{"accessToken","refreshToken",
//                   "expiresAt"(ISO 8601),..}}
// ---------------------------------------------------------------------

pub const CLINE_API_BASE: &str = "https://api.cline.bot";
const WORKOS_API_BASE: &str = "https://api.workos.com";
/// Cline's production WorkOS client id (cline/cline
/// sdk/packages/shared/src/runtime/cline-environment.ts).
const CLINE_WORKOS_CLIENT_ID: &str = "client_01K3A541FN8TA3EPPHTD2325AR";

/// A Cline account session backing an escrow entry. The current access
/// token is mirrored into the entry's secret so the proxy's synchronous
/// substitution path never waits on a refresh.
#[derive(Clone, Debug, serde::Serialize, Deserialize)]
pub struct ClineSession {
    pub refresh_token: String,
    pub expires_at: i64,
    pub api_base_url: String,
}

impl ClineSession {
    pub fn secret_name(entry: &str) -> String {
        format!("cline-oauth:{entry}")
    }

    pub fn load(settings: &Settings, entry: &str) -> Option<Self> {
        settings
            .secret(&Self::secret_name(entry))
            .and_then(|text| serde_json::from_str(&text).ok())
    }

    pub fn expires_soon(&self) -> bool {
        // Cline's own SDK refreshes 5 minutes early; match it.
        self.expires_at - 300 <= chrono::Utc::now().timestamp()
    }
}

/// Device-flow login state, per escrow entry, for the UI to poll.
#[derive(Clone, Debug, serde::Serialize)]
#[serde(tag = "state", rename_all = "snake_case")]
pub enum ClineLoginState {
    /// Show this code; the user confirms it in the browser.
    WaitingForUser {
        user_code: String,
        verification_uri: String,
    },
    Connected,
    Failed {
        error: String,
    },
}

#[derive(Clone, Default)]
pub struct ClineFlows(Arc<Mutex<HashMap<String, ClineLoginState>>>);

impl ClineFlows {
    pub fn status(&self, entry: &str) -> Option<ClineLoginState> {
        self.0.lock().expect("cline flows lock").get(entry).cloned()
    }

    fn set(&self, entry: &str, state: ClineLoginState) {
        self.0
            .lock()
            .expect("cline flows lock")
            .insert(entry.to_owned(), state);
    }

    /// Starts the device flow: requests a device authorization, records
    /// the user code for display, and spawns the background poller that
    /// completes the login without any callback into this process.
    pub async fn start(&self, entry: &str, settings: &Settings) -> Result<ClineLoginState> {
        let device = request_device_authorization().await?;
        let shown = ClineLoginState::WaitingForUser {
            user_code: device.user_code.clone(),
            verification_uri: device
                .verification_uri_complete
                .clone()
                .unwrap_or_else(|| device.verification_uri.clone()),
        };
        self.set(entry, shown.clone());

        let flows = self.clone();
        let settings = settings.clone();
        let entry = entry.to_owned();
        tokio::spawn(async move {
            match poll_and_register(&device, &settings, &entry).await {
                Ok(()) => flows.set(&entry, ClineLoginState::Connected),
                Err(error) => flows.set(
                    &entry,
                    ClineLoginState::Failed {
                        error: format!("{error:#}"),
                    },
                ),
            }
        });
        Ok(shown)
    }
}

struct DeviceAuthorization {
    device_code: String,
    user_code: String,
    verification_uri: String,
    verification_uri_complete: Option<String>,
    expires_in: u64,
    interval: u64,
}

async fn request_device_authorization() -> Result<DeviceAuthorization> {
    let response = reqwest::Client::new()
        .post(format!(
            "{WORKOS_API_BASE}/user_management/authorize/device"
        ))
        .form(&[("client_id", CLINE_WORKOS_CLIENT_ID)])
        .send()
        .await
        .context("device authorization request")?;
    let status = response.status();
    let json: serde_json::Value = response
        .json()
        .await
        .context("parse device authorization")?;
    if !status.is_success() {
        anyhow::bail!("device authorization returned {status}: {json}");
    }
    let field = |name: &str| {
        json.get(name)
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned)
            .with_context(|| format!("no {name} in device authorization"))
    };
    Ok(DeviceAuthorization {
        device_code: field("device_code")?,
        user_code: field("user_code")?,
        verification_uri: field("verification_uri")?,
        verification_uri_complete: json
            .get("verification_uri_complete")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned),
        expires_in: json
            .get("expires_in")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(300),
        interval: json
            .get("interval")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(5)
            .max(1),
    })
}

/// Polls WorkOS until the user confirms the code, then registers the
/// WorkOS tokens with Cline's backend and stores the session.
async fn poll_and_register(
    device: &DeviceAuthorization,
    settings: &Settings,
    entry: &str,
) -> Result<()> {
    let client = reqwest::Client::new();
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(device.expires_in);
    let mut interval = device.interval;
    let (workos_access, workos_refresh) = loop {
        if std::time::Instant::now() > deadline {
            anyhow::bail!("device authorization timed out; start the sign-in again");
        }
        let response = client
            .post(format!("{WORKOS_API_BASE}/user_management/authenticate"))
            .form(&[
                ("grant_type", "urn:ietf:params:oauth:grant-type:device_code"),
                ("device_code", &device.device_code),
                ("client_id", CLINE_WORKOS_CLIENT_ID),
            ])
            .send()
            .await
            .context("token poll")?;
        let ok = response.status().is_success();
        let json: serde_json::Value = response.json().await.unwrap_or_default();
        if ok {
            let access = json
                .get("access_token")
                .and_then(serde_json::Value::as_str)
                .context("no access_token from WorkOS")?;
            let refresh = json
                .get("refresh_token")
                .and_then(serde_json::Value::as_str)
                .context("no refresh_token from WorkOS")?;
            break (access.to_owned(), refresh.to_owned());
        }
        match json.get("error").and_then(serde_json::Value::as_str) {
            Some("authorization_pending") => {}
            Some("slow_down") => interval += 1,
            Some(terminal) => anyhow::bail!(
                "authorization failed: {terminal}{}",
                json.get("error_description")
                    .and_then(serde_json::Value::as_str)
                    .map(|d| format!(" - {d}"))
                    .unwrap_or_default()
            ),
            None => anyhow::bail!("unexpected poll response: {json}"),
        }
        tokio::time::sleep(std::time::Duration::from_secs(interval)).await;
    };
    // Exchange WorkOS tokens for a Cline session.
    let data = cline_token_request(
        &format!("{CLINE_API_BASE}/api/v1/auth/register"),
        &serde_json::json!({
            "accessToken": [REDACTED],
            "refreshToken": [REDACTED],
        }),
    )
    .await
    .context("Cline token registration")?;
    store_cline_session(settings, entry, &data, CLINE_API_BASE)
}

/// Refreshes a Cline session and re-mirrors the access token into the
/// entry's secret. Returns the new access token.
pub async fn refresh_cline(settings: &Settings, entry: &str) -> Result<String> {
    let session = ClineSession::load(settings, entry).context("no Cline session to refresh")?;
    let body = serde_json::json!({
        "refreshToken": [REDACTED],
        "grantType": "refresh_token",
    });
    let data = cline_token_request(
        &format!("{}/api/v1/auth/refresh", session.api_base_url),
        &body,
    )
    .await
    .context("Cline token refresh (reconnect in settings if this persists)")?;
    store_cline_session(settings, entry, &data, &session.api_base_url)?;
    data.get("accessToken")
        .and_then(serde_json::Value::as_str)
        .map(str::to_owned)
        .context("no accessToken after refresh")
}

async fn cline_token_request(url: &str, body: &serde_json::Value) -> Result<serde_json::Value> {
    let response = reqwest::Client::new()
        .post(url)
        .json(body)
        .send()
        .await
        .context("request")?;
    let status = response.status();
    let json: serde_json::Value = response.json().await.context("parse response")?;
    if !status.is_success()
        || json.get("success").and_then(serde_json::Value::as_bool) != Some(true)
    {
        anyhow::bail!("{url} returned {status}: {json}");
    }
    json.get("data").cloned().context("no data in response")
}

fn store_cline_session(
    settings: &Settings,
    entry: &str,
    data: &serde_json::Value,
    api_base_url: &str,
) -> Result<()> {
    let access = data
        .get("accessToken")
        .and_then(serde_json::Value::as_str)
        .context("no accessToken")?;
    let refresh = data
        .get("refreshToken")
        .and_then(serde_json::Value::as_str)
        .map(str::to_owned)
        // Rotation optional: keep the old refresh token when absent.
        .or_else(|| ClineSession::load(settings, entry).map(|s| s.refresh_token))
        .context("no refreshToken")?;
    let expires_at = data
        .get("expiresAt")
        .and_then(serde_json::Value::as_str)
        .and_then(|iso| chrono::DateTime::parse_from_rfc3339(iso).ok())
        .map(|dt| dt.timestamp())
        .context("no parseable expiresAt")?;
    let session = ClineSession {
        refresh_token: refresh,
        expires_at,
        api_base_url: api_base_url.to_owned(),
    };
    settings.set_cline_session(entry, &session, access)
}

/// Background maintenance: refresh any Cline session nearing expiry so
/// the mirrored access token stays valid without blocking the proxy.
pub async fn refresh_expiring_cline_sessions(settings: &Settings) {
    for entry in settings.entries() {
        if let Some(session) = ClineSession::load(settings, &entry.name)
            && session.expires_soon()
            && let Err(error) = refresh_cline(settings, &entry.name).await
        {
            tracing::warn!(%error, entry = %entry.name, "Cline session refresh failed");
        }
    }
}

"""Script-only Linux guest configuration; standard library, explicit test paths."""
import base64
import datetime
import hashlib
import json
import os
from pathlib import Path
import shlex
import socket
import subprocess
import sys
import tempfile
import urllib.parse
import urllib.request

MARKER = "# Friendzone guest environment (managed)"
SYSTEM_CA = Path("/usr/local/share/ca-certificates/friendzone-local-ca.crt")
SYSTEM_CA_STATE = "linux-system-ca.json"
PROXY_VARIABLES = ("HTTP_PROXY", "HTTPS_PROXY", "http_proxy", "https_proxy", "CARGO_HTTP_PROXY")


def atomic_write(path, text, mode=0o600):
    path = Path(path).resolve()
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(dir=path.parent, prefix=".friendzone-")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as stream:
            stream.write(text)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, mode)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def certificate_digest(pem):
    """Validate one bounded PEM certificate and return its DER SHA-256."""
    if not isinstance(pem, str) or len(pem.encode("utf-8")) > 128 * 1024:
        raise ValueError("Friendzone CA is missing or exceeds 128 KiB")
    begin = "-----BEGIN CERTIFICATE-----"
    end = "-----END CERTIFICATE-----"
    if pem.count(begin) != 1 or pem.count(end) != 1:
        raise ValueError("Friendzone CA must contain exactly one PEM certificate")
    before, encoded = pem.split(begin, 1)
    encoded, after = encoded.split(end, 1)
    if before.strip() or after.strip():
        raise ValueError("Friendzone CA contains data outside its PEM certificate")
    try:
        der = base64.b64decode("".join(encoded.split()), validate=True)
    except Exception as error:
        raise ValueError("Friendzone CA contains invalid PEM base64") from error
    if not der:
        raise ValueError("Friendzone CA certificate is empty")
    return hashlib.sha256(der).hexdigest()


def _command_path(name, known):
    """Resolve only fixed administrator-owned paths, never the guest's PATH."""
    for candidate in known:
        if Path(candidate).is_file():
            return candidate
    return None


def install_linux_ca(cert, config, destination=SYSTEM_CA, run=None,
                     updater=None, installer=None, remover=None, privilege=None):
    """Install/rotate only Friendzone's owned Debian-family native trust anchor."""
    cert, config, destination = map(lambda path: Path(path).absolute(),
                                    (cert, config, destination))
    pem = cert.read_text(encoding="utf-8")
    digest = certificate_digest(pem)
    state_path = config / SYSTEM_CA_STATE
    state = None
    if state_path.exists():
        try:
            state = json.loads(state_path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as error:
            raise ValueError("Invalid Friendzone Linux CA ownership state; repair or remove " + str(state_path)) from error
        if (not isinstance(state, dict) or state.get("version") != 1 or
                not isinstance(state.get("managed"), bool) or
                not isinstance(state.get("sha256"), str) or
                len(state["sha256"]) != 64 or
                any(character not in "0123456789abcdef" for character in state["sha256"])):
            raise ValueError("Invalid Friendzone Linux CA ownership state; repair or remove " + str(state_path))
    previous = destination.read_bytes() if destination.exists() else None
    previous_digest = certificate_digest(previous.decode("utf-8")) if previous is not None else None
    if state is None and previous is not None and previous_digest != digest:
        raise ValueError("Refusing to overwrite unowned system CA file " + str(destination))
    if state is not None:
        if state["managed"]:
            if previous is not None and previous_digest != state["sha256"]:
                raise ValueError("Friendzone-owned system CA was changed externally; refusing to overwrite " + str(destination))
        elif previous_digest != state["sha256"] or digest != state["sha256"]:
            raise ValueError("A pre-existing system CA occupies " + str(destination) + "; Friendzone will not replace it")
    managed = state["managed"] if state is not None else previous is None
    if previous_digest == digest:
        if state is None:
            config.mkdir(parents=True, exist_ok=True)
            atomic_write(state_path, json.dumps(
                dict(version=1, managed=False, sha256=digest), indent=2) + "\n")
        return dict(installed=False, managed=managed, sha256=digest, destination=str(destination))

    run = run or subprocess.run
    updater = updater or _command_path("update-ca-certificates", (
        "/usr/sbin/update-ca-certificates", "/usr/bin/update-ca-certificates"))
    installer = installer or _command_path("install", ("/usr/bin/install", "/bin/install"))
    remover = remover or _command_path("rm", ("/usr/bin/rm", "/bin/rm"))
    if not updater or not installer or not remover:
        raise ValueError("Linux native CA setup requires the ca-certificates package and install command")
    if privilege is None:
        if hasattr(os, "geteuid") and os.geteuid() == 0:
            privilege = []
        else:
            sudo = _command_path("sudo", ("/usr/bin/sudo", "/bin/sudo"))
            if not sudo:
                raise ValueError("Linux native CA setup requires sudo; install sudo or run from a root login")
            privilege = [sudo]
    privilege = list(privilege)
    config.mkdir(parents=True, exist_ok=True)
    rollback = config / ".friendzone-system-ca-rollback.crt"
    if previous is not None:
        atomic_write(rollback, previous.decode("utf-8"))
    attempted = False
    def privileged(arguments):
        return run(privilege + arguments, check=True)
    def restore():
        if previous is None:
            privileged([remover, "-f", "--", str(destination)])
        else:
            privileged([installer, "-D", "-m", "0644", "--", str(rollback), str(destination)])
        privileged([updater])
    try:
        print("Installing Friendzone CA into Linux system trust; sudo may prompt.")
        attempted = True
        privileged([installer, "-D", "-m", "0644", "--", str(cert), str(destination)])
        privileged([updater])
        atomic_write(state_path, json.dumps(dict(version=1, managed=managed, sha256=digest), indent=2) + "\n")
    except Exception as error:
        try:
            if attempted:
                restore()
        except Exception:
            raise RuntimeError("Linux CA update failed and automatic rollback also failed; inspect " + str(destination)) from error
        raise RuntimeError("Linux CA update failed and was rolled back; verify sudo and update-ca-certificates") from error
    finally:
        try:
            rollback.unlink()
        except FileNotFoundError:
            pass
    return dict(installed=True, managed=managed, sha256=digest, destination=str(destination))


def provider_update(path, fake, oauth=False):
    root = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
    if not isinstance(root, dict) or root.get("version", 1) != 1:
        raise ValueError("Unsupported Cline providers.json; no configuration changed")
    root["version"] = 1
    root.setdefault("modes", {})
    providers = root.setdefault("providers", {})
    if not isinstance(providers, dict):
        raise ValueError("Cline providers must be an object")
    entry = providers.setdefault("cline", {"settings": {"provider": "cline"}})
    if not isinstance(entry, dict) or not isinstance(entry.get("settings"), dict):
        raise ValueError("Invalid Cline provider settings")
    if oauth:
        entry["settings"].pop("apiKey", None)
        # This is an OAuth-shaped, guest-only facade. Friendzone owns the real
        # refresh token; the far-future local expiry prevents Cline from trying
        # to redeem credentials that deliberately do not exist in the guest.
        entry["settings"]["auth"] = {
            "accessToken": "workos:" + fake,
            "expiresAt": 253402300799000,
        }
        entry["tokenSource"] = "oauth"
    else:
        entry["settings"]["apiKey"] = fake
        entry["settings"].pop("auth", None)
        entry["tokenSource"] = "manual"
    entry["updatedAt"] = datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")
    root.setdefault("lastUsedProvider", "cline")
    return json.dumps(root, ensure_ascii=False, indent=2) + "\n"


def profile_update(old, activation, env, home):
    hook = MARKER + "\nif [ -r {0} ]; then . {0}; fi\n".format(shlex.quote(str(activation)))
    if hook in old:
        return old
    # Upgrade the previous Rust installer's always-quoted spelling in place.
    quoted = "'" + str(activation).replace("'", "'\"'\"'") + "'"
    previous_hook = MARKER + "\nif [ -r {0} ]; then . {0}; fi\n".format(quoted)
    if previous_hook in old:
        return old.replace(previous_hook, hook)
    if MARKER in old:
        raise ValueError("Existing Friendzone hook uses another directory; remove it before relocating configuration")
    candidates = set()
    for target in (activation, env):
        for command in (".", "source"):
            candidates.update((f"{command} {target}", f"{command} {shlex.quote(str(target))}", f'{command} "{target}"'))
            try:
                relative = target.relative_to(home).as_posix()
                candidates.update((f"{command} ~/{relative}", f'{command} "$HOME/{relative}"', f"{command} $HOME/{relative}"))
            except ValueError:
                pass
    lines = old.splitlines(keepends=True)
    matches = [i for i, line in enumerate(lines) if line.strip() in candidates]
    if matches:
        return "".join(hook if i == matches[0] else "" if i in matches else line for i, line in enumerate(lines))
    return hook + "\n" + old


def configure(data, home, config, zdotdir, environ):
    """Only these explicit paths are written; caller owns network admission."""
    home, config, zdotdir = map(lambda p: Path(p).absolute(), (home, config, zdotdir))
    cert = config / "friendzone-ca.pem"
    env = config / "friendzone-env.sh"
    activation = config / "activate.sh"
    wrapper = config / "bash-env.sh"
    old_hook = config / "previous-bash-env"
    previous = old_hook.read_text(encoding="utf-8") if old_hook.exists() else environ.get("BASH_ENV", "")
    if previous == str(wrapper):
        previous = ""
    old_environment = env.read_text(encoding="utf-8") if env.exists() else ""
    old_github_token = None
    previous_proxy = None
    retired_proxy_path = config / "retired-proxy-values.json"
    old_proxy_values = json.loads(retired_proxy_path.read_text(encoding="utf-8")) if retired_proxy_path.exists() else {}
    if old_environment.startswith("# Friendzone guest environment\n"):
        for line in old_environment.splitlines():
            try:
                fields = shlex.split(line)
            except ValueError:
                fields = []
            if len(fields) == 2 and fields[0] == "export" and fields[1].startswith("GITHUB_TOKEN="):
                if old_github_token is not None:
                    raise ValueError("Invalid previous Friendzone GITHUB_TOKEN environment")
                old_github_token = fields[1].split("=", 1)[1]
            if len(fields) == 2 and fields[0] == "export" and "=" in fields[1]:
                key, value = fields[1].split("=", 1)
                if key == "FZ_PROXY":
                    previous_proxy = value
                if key in PROXY_VARIABLES:
                    old_proxy_values[key] = value
    legacy_idle = "export CLINE_PLUGIN_IDLE_TIMEOUT_MS=90000000\n"
    legacy_idle_marker = config / "remove-legacy-cline-idle-timeout"
    # The old generated file proves ownership. Preserve any user-authored value.
    remove_legacy_idle = legacy_idle_marker.exists() or (legacy_idle in old_environment and old_environment.count("CLINE_PLUGIN_IDLE_TIMEOUT_MS") == 1)
    origin = urllib.parse.urlsplit(data["broker"])
    proxy_host = "[" + origin.hostname + "]" if ":" in origin.hostname else origin.hostname
    proxy = "http://{}:{}".format(proxy_host, data["proxy_port"])
    if previous_proxy and previous_proxy != proxy:
        old_proxy_values["CARGO_HTTP_PROXY"] = previous_proxy
    values = dict(data["fakes"])
    values.update(FZ_HOST=origin.hostname, FZ_BROKER=data["broker"], FZ_PROXY=proxy,
                  FZ_PAC_URL=data["broker"] + "/bootstrap/proxy.pac",
                  FZ_PROXY_HOSTS=",".join(data["proxy_hosts"]))
    for key in ("NODE_EXTRA_CA_CERTS", "REQUESTS_CA_BUNDLE", "SSL_CERT_FILE", "GIT_SSL_CAINFO", "GIT_PROXY_SSL_CAINFO", "CARGO_HTTP_CAINFO"):
        values[key] = str(cert)
    git_config_text = data.get("git_credential_config") or ""
    git_config = config / "friendzone.gitconfig"
    if not git_config_text.startswith("# Friendzone managed Git configuration v1\n"):
        raise ValueError("Invalid managed Git credential configuration")
    expected = {"GIT_CONFIG_COUNT": "1", "GIT_CONFIG_KEY_0": "include.path", "GIT_CONFIG_VALUE_0": str(git_config)}
    injected = {key: value for key, value in environ.items()
                if key == "GIT_CONFIG_PARAMETERS" or key == "GIT_CONFIG_COUNT" or
                key.startswith("GIT_CONFIG_KEY_") or key.startswith("GIT_CONFIG_VALUE_")}
    if injected and injected != expected:
        raise ValueError("Existing GIT_CONFIG_* environment entries conflict with Friendzone Git authentication")
    values.update(expected)
    content = "# Friendzone guest environment\n" + "".join(f"export {key}={shlex.quote(value)}\n" for key, value in values.items())
    for key in PROXY_VARIABLES:
        old_value = old_proxy_values.get(key, proxy)
        content += 'if [ "${{{0}-}}" = {1} ] || [ "${{{0}-}}" = {2} ]; then unset {0}; fi\n'.format(key, shlex.quote(old_value), shlex.quote(proxy))
    if old_github_token is not None and "GITHUB_TOKEN" not in values:
        content += "if [ \"${{GITHUB_TOKEN-}}\" = {0} ]; then unset GITHUB_TOKEN; fi\n".format(shlex.quote(old_github_token))
    if remove_legacy_idle:
        marker = shlex.quote(str(legacy_idle_marker))
        content += "if [ -r {0} ]; then\n  if [ \"${{CLINE_PLUGIN_IDLE_TIMEOUT_MS-}}\" = 90000000 ]; then unset CLINE_PLUGIN_IDLE_TIMEOUT_MS; fi\n  rm -f -- {0}\nfi\n".format(marker)
    exclusions = ",".join([origin.hostname, "localhost", "127.0.0.1", "::1", "[::1]"] + data["infrastructure_no_proxy"])
    content += '_fz_rest=' + shlex.quote(exclusions + ',') + '"${NO_PROXY:-},${no_proxy:-},"\n'
    content += '''
_fz_list=
while [ -n "$_fz_rest" ]; do
  _fz_item=${_fz_rest%%,*}; _fz_rest=${_fz_rest#*,}
  _fz_item=${_fz_item#"${_fz_item%%[![:space:]]*}"}; _fz_item=${_fz_item%"${_fz_item##*[![:space:]]}"}
  [ -n "$_fz_item" ] || continue
  case ,$_fz_list, in *,"$_fz_item",*) ;; *) _fz_list="${_fz_list:+$_fz_list,}$_fz_item" ;; esac
done
export NO_PROXY="$_fz_list" no_proxy="$_fz_list"
unset _fz_rest _fz_list _fz_item
'''
    source = ". " + shlex.quote(str(env)) + "\n"
    # Explicit activation selects one proxy for this process and future children.
    # Cargo's native setting takes precedence over Cargo/Git config-file proxies.
    compatibility = source + ''.join('export {0}="$FZ_PROXY"\n'.format(key)
        for key in PROXY_VARIABLES)
    compatibility += 'export BASH_ENV=' + shlex.quote(str(config / "friendzone-proxy-env.sh")) + '\n'
    edits = ([(legacy_idle_marker, "Friendzone previously managed the exact value 90000000; activation removes only that value.\n")] if remove_legacy_idle else []) + [(git_config, git_config_text), (cert, data["ca"]), (env, content), (old_hook, previous),
             (config / "friendzone-proxy-env.sh", compatibility),
             (retired_proxy_path, json.dumps(old_proxy_values) + "\n"),
             (activation, source + "export BASH_ENV=" + shlex.quote(str(wrapper)) + "\n"),
             (wrapper, ("if [ -r {0} ]; then . {0}; fi\n".format(shlex.quote(previous)) if previous else "") + source)]
    profiles = {home / ".profile", home / ".bashrc", zdotdir / ".zshenv"}
    profiles.update(home / name for name in (".bash_profile", ".bash_login") if (home / name).exists())
    backups = []
    if git_config.exists() and not git_config.read_text(encoding="utf-8").startswith("# Friendzone managed Git configuration v1\n"):
        raise ValueError("Unmanaged friendzone.gitconfig exists; configuration unchanged")
    cline_home = Path(environ.get("CLINE_DIR", "").strip() or home / ".cline").absolute()
    plugin_path = cline_home / "plugins/friendzone.js"
    plugin_config = cline_home / "friendzone.json"
    plugin = base64.b64decode(data["plugin"], validate=True).decode("utf-8")
    if not plugin.startswith("// Friendzone managed plugin v1."):
        raise ValueError("Invalid Friendzone plugin payload")
    if plugin_path.exists():
        old_plugin = plugin_path.read_text(encoding="utf-8")
        if not old_plugin.startswith("// Friendzone managed plugin v1."):
            raise ValueError("Unmanaged friendzone.js already exists; configuration unchanged")
        backups.append((plugin_path.with_name("friendzone.js.backup"), old_plugin))
    if plugin_config.exists():
        old_config = json.loads(plugin_config.read_text(encoding="utf-8"))
        if not isinstance(old_config, dict) or old_config.get("managed_by") != "friendzone":
            raise ValueError("Unmanaged Friendzone plugin configuration; configuration unchanged")
        backups.append((plugin_config.with_name("friendzone.json.backup"), plugin_config.read_text(encoding="utf-8")))
    edits.extend([(plugin_path, plugin), (plugin_config, json.dumps(dict(managed_by="friendzone",broker=data["broker"],container=data["container"]), indent=2)+"\n")])
    for path in sorted(profiles):
        old = path.read_text(encoding="utf-8") if path.exists() else ""
        updated = profile_update(old, activation, env, home)
        if updated != old:
            edits.append((path, updated))
            if path.exists():
                backups.append((path.with_name(path.name + ".friendzone-backup"), old))
    if "CLINE_API_KEY" in data["fakes"]:
        provider = home / ".cline/data/settings/providers.json"
        edits.append((provider, provider_update(provider, data["fakes"]["CLINE_API_KEY"], bool(data.get("cline_oauth")))))
        if provider.exists():
            backups.append((provider.with_name("providers.json.friendzone-backup"), provider.read_text(encoding="utf-8")))
    # All parsing and profile conflict checks complete before the first write.
    for path, text in backups:
        if not path.exists():
            atomic_write(path, text)
    for path, text in edits:
        mode = path.stat().st_mode & 0o777 if path in profiles and path.exists() else 0o600
        atomic_write(path, text, mode)
    return activation


def main(encoded):
    if not sys.platform.startswith("linux"):
        raise ValueError("Select the Windows script for a Windows guest")
    if os.environ.get("SUDO_USER"):
        raise ValueError("Run this script as the guest user without sudo")
    data = json.loads(base64.b64decode(encoded))
    data["container"] = data["container"] or socket.gethostname()
    if not data["container"] or ":" in data["container"] or len(data["container"].encode()) > 128:
        raise ValueError("Invalid guest name")
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *args, **kwargs):
            return None
    client = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect())
    url = data["broker"] + "/bootstrap/hello?" + urllib.parse.urlencode({"container": data["container"]})
    with client.open(url, timeout=10) as response:
        approval = json.load(response)
    canonical = approval.get("container") if isinstance(approval, dict) else None
    if not isinstance(canonical, str) or not canonical or ":" in canonical or len(canonical.encode()) > 128 or any(ord(character) < 32 or ord(character) == 127 for character in canonical):
        raise ValueError("Friendzone registration did not return a valid guest name; no guest settings were changed")
    requested = data["container"]
    data["container"] = canonical
    home = Path.home()
    config = Path(os.environ.get("XDG_CONFIG_HOME", str(home / ".config"))) / "friendzone"
    activation = configure(data, home, config, os.environ.get("ZDOTDIR", str(home)), os.environ)
    trust = install_linux_ca(config / "friendzone-ca.pem", config)
    print("Linux native trust ready at " + trust["destination"] + ".")
    if canonical != requested:
        print("Requested guest name " + requested + " was replaced with " + canonical + " because this VM source IP is already pinned to that guest.")
    message = approval.get("message") or ("Approved and pinned." if approval.get("approved") else "Use Approve + pin IP in the host Inbox.")
    print("Configured guest " + canonical + ". " + str(message))
    print("Installed the Friendzone Cline plugin for async GraphQL, reviewed Git publication, and session updates.")
    print("Activate this terminal, then restart guest Cline so it inherits the environment:\n  . " + shlex.quote(str(activation)))
    print("Direct-by-default setup: set your application's PAC URL to " + data["broker"] + "/bootstrap/proxy.pac")
    print("For Cline CLI or other non-PAC clients that need escrow, use the explicit compatibility profile:\n  . " + shlex.quote(str(config / "friendzone-proxy-env.sh")))

//! Read-only Cline MCP adapter. Contract: cline/cline b18de090,
//! core/src/extensions/mcp/config-loader.ts (nested and legacy entries).
//! Cline owns OAuth refresh. We never execute commands or write its file.

use std::{
    collections::BTreeMap,
    path::{Path, PathBuf},
};

use anyhow::{Context, Result, bail};
use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ClineSource {
    pub path: String,
    pub server: String,
}

#[derive(Serialize)]
pub struct Candidate {
    pub server: String,
    pub url: Option<String>,
    pub supported: bool,
    pub reason: String,
}

/// Cline b18de090 shared/src/storage/paths.ts: use the broker process's
/// environment/home, not the browser's OS or a guest path. Resolving a
/// suggestion does not read the file, and it need not exist yet.
pub fn default_settings_path() -> Option<PathBuf> {
    settings_path_from_env(|name| std::env::var(name).ok(), dirs::home_dir())
        .and_then(|path| std::path::absolute(path).ok())
}

fn settings_path_from_env(
    env: impl Fn(&str) -> Option<String>,
    os_home: Option<PathBuf>,
) -> Option<PathBuf> {
    let value = |name| {
        env(name)
            .map(|v| v.trim().to_owned())
            .filter(|v| !v.is_empty())
    };
    if let Some(path) = value("CLINE_MCP_SETTINGS_PATH") {
        return Some(path.into());
    }
    let data_dir = if let Some(dir) = value("CLINE_DATA_DIR") {
        PathBuf::from(dir)
    } else {
        let cline_dir = if let Some(dir) = value("CLINE_DIR") {
            PathBuf::from(dir)
        } else {
            let home = value("HOME")
                .filter(|v| v != "~")
                .or_else(|| value("USERPROFILE"))
                .or_else(|| {
                    value("HOMEDRIVE")
                        .zip(value("HOMEPATH"))
                        .map(|(drive, path)| format!("{drive}{path}"))
                })
                .map(PathBuf::from)
                .or(os_home)?;
            home.join(".cline")
        };
        cline_dir.join("data")
    };
    Some(data_dir.join("settings").join("cline_mcp_settings.json"))
}

fn read_servers(path: &str) -> Result<serde_json::Map<String, Value>> {
    if !Path::new(path).is_absolute() {
        bail!("Cline settings path must be absolute on the broker host (not a guest path)");
    }
    let text = std::fs::read_to_string(path).context("read host Cline MCP settings")?;
    let root: Value = serde_json::from_str(&text).context("parse Cline MCP settings")?;
    root.get("mcpServers")
        .and_then(Value::as_object)
        .cloned()
        .context("expected an mcpServers object")
}

fn transport(entry: &Value) -> Result<&Value> {
    if !entry.is_object() {
        bail!("server entry must be an object");
    }
    let transport = entry.get("transport").unwrap_or(entry);
    if !transport.is_object() {
        bail!("transport must be an object");
    }
    let kind = if entry.get("transport").is_some() {
        transport
            .get("type")
            .and_then(Value::as_str)
            .context("nested transport requires type")?
    } else {
        entry
            .get("type")
            .or_else(|| entry.get("transportType"))
            .and_then(Value::as_str)
            .unwrap_or(if entry.get("command").is_some() {
                "stdio"
            } else {
                "sse"
            })
    };
    if kind != "streamableHttp"
        && !(entry.get("type").is_none() && entry.get("transport").is_none() && kind == "http")
    {
        bail!("{kind} transport is not supported; no host commands are executed");
    }
    if entry
        .get("disabled")
        .is_some_and(|v| v != &Value::Bool(false))
    {
        bail!("server is disabled or has an invalid disabled flag in Cline");
    }
    Ok(transport)
}

fn endpoint(entry: &Value) -> Result<String> {
    let raw = transport(entry)?
        .get("url")
        .and_then(Value::as_str)
        .context("missing server URL")?;
    let url = reqwest::Url::parse(raw).context("invalid server URL")?;
    if !matches!(url.scheme(), "http" | "https")
        || url.host_str().is_none()
        || !url.username().is_empty()
        || url.password().is_some()
        || url.fragment().is_some()
    {
        bail!("expected HTTP(S) URL without embedded credentials or fragment");
    }
    Ok(raw.to_owned())
}

pub fn preview(path: &str) -> Result<Vec<Candidate>> {
    let servers = read_servers(path)?;
    let mut candidates: Vec<_> = servers
        .into_iter()
        .map(|(server, entry)| match endpoint(&entry) {
            Ok(url) => Candidate {
                server,
                url: Some(url),
                supported: true,
                reason:
                    "Read-only Cline link; select tools and guests, then validate before applying"
                        .into(),
            },
            Err(error) => Candidate {
                server,
                url: None,
                supported: false,
                reason: error.to_string(),
            },
        })
        .collect();
    candidates.sort_by(|a, b| a.server.cmp(&b.server));
    Ok(candidates)
}

/// Read a complete current Cline snapshot per upstream request. Never
/// follow a moved endpoint with old credentials: re-import explicitly.
pub fn headers(source: &ClineSource, expected_url: &str) -> Result<BTreeMap<String, String>> {
    let servers = read_servers(&source.path)?;
    let entry = servers
        .get(&source.server)
        .context("linked Cline server was removed")?;
    if endpoint(entry)? != expected_url {
        bail!("linked Cline URL changed; review and re-import it");
    }
    let mut headers: BTreeMap<String, String> = match transport(entry)?.get("headers") {
        Some(value) => {
            serde_json::from_value(value.clone()).context("Cline headers must be a string map")?
        }
        None => BTreeMap::new(),
    };
    if entry
        .pointer("/oauth/authorizationRequired")
        .and_then(Value::as_bool)
        == Some(true)
    {
        bail!("linked server requires authorization; reconnect it in Cline on the host");
    }
    if let Some(token) = entry
        .pointer("/oauth/tokens/access_token")
        .and_then(Value::as_str)
        .filter(|v| !v.is_empty())
    {
        headers.retain(|name, _| !name.eq_ignore_ascii_case("authorization"));
        headers.insert("Authorization".into(), format!("Bearer {token}"));
    }
    for (name, value) in &headers {
        let name = reqwest::header::HeaderName::from_bytes(name.as_bytes())
            .context("invalid Cline header name")?;
        if matches!(
            name.as_str(),
            "host"
                | "content-length"
                | "transfer-encoding"
                | "connection"
                | "proxy-authorization"
                | "mcp-session-id"
                | "mcp-protocol-version"
        ) {
            bail!(
                "Cline header {} cannot override broker transport state",
                name
            );
        }
        reqwest::header::HeaderValue::from_str(value).context("invalid Cline header value")?;
    }
    Ok(headers)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn default_path_honors_cline_override_precedence() {
        let mut env = BTreeMap::from([
            ("CLINE_MCP_SETTINGS_PATH", " explicit.json "),
            ("CLINE_DATA_DIR", " data-override "),
            ("CLINE_DIR", " cline-override "),
            ("HOME", "host-home"),
        ]);
        let resolve = |env: &BTreeMap<&str, &str>| {
            settings_path_from_env(|name| env.get(name).map(|v| (*v).into()), None).unwrap()
        };
        assert_eq!(resolve(&env), PathBuf::from("explicit.json"));
        env.insert("CLINE_MCP_SETTINGS_PATH", " \t ");
        assert_eq!(
            resolve(&env),
            Path::new("data-override").join("settings/cline_mcp_settings.json")
        );
        env.remove("CLINE_DATA_DIR");
        assert_eq!(
            resolve(&env),
            Path::new("cline-override").join("data/settings/cline_mcp_settings.json")
        );
        env.remove("CLINE_DIR");
        assert_eq!(
            resolve(&env),
            Path::new("host-home").join(".cline/data/settings/cline_mcp_settings.json")
        );
    }

    #[test]
    fn default_path_uses_cline_home_fallbacks() {
        let resolve = |entries: &[(&str, &str)], fallback: Option<PathBuf>| {
            settings_path_from_env(
                |name| {
                    entries
                        .iter()
                        .find(|(key, _)| *key == name)
                        .map(|(_, value)| (*value).into())
                },
                fallback,
            )
        };
        let suffix = ".cline/data/settings/cline_mcp_settings.json";
        assert_eq!(
            resolve(&[("HOME", "~"), ("USERPROFILE", " profile ")], None),
            Some(Path::new("profile").join(suffix))
        );
        assert_eq!(
            resolve(&[("HOMEDRIVE", "C:"), ("HOMEPATH", "\\Users\\guest")], None),
            Some(Path::new("C:\\Users\\guest").join(suffix))
        );
        assert_eq!(
            resolve(&[], Some("os-home".into())),
            Some(Path::new("os-home").join(suffix))
        );
        assert_eq!(resolve(&[], None), None);
    }

    #[test]
    fn cline_contract_handles_nested_legacy_and_unsupported_shapes() {
        let dir = std::env::temp_dir().join(format!("fz-import-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("cline_mcp_settings.json");
        let root = json!({"mcpServers":{
            "nested":{"transport":{"type":"streamableHttp","url":"https://example.test/mcp","headers":{"x-api-key":"host-secret"}}},
            "legacy":{"transportType":"http","url":"https://example.test/mcp"},
            "stdio":{"command":"do-not-run","args":[],"env":{"KEY":"secret"}},
            "sse-default":{"url":"https://example.test/sse"},
            "disabled":{"transport":{"type":"streamableHttp","url":"https://example.test/mcp"},"disabled":true},
            "null":null,
            "array":[]
        }});
        std::fs::write(&path, serde_json::to_vec(&root).unwrap()).unwrap();
        let candidates = preview(path.to_str().unwrap()).unwrap();
        assert_eq!(candidates.iter().filter(|c| c.supported).count(), 2);
        assert!(
            !serde_json::to_string(&candidates)
                .unwrap()
                .contains("host-secret")
        );
        let source = ClineSource {
            path: path.to_str().unwrap().into(),
            server: "nested".into(),
        };
        assert_eq!(
            headers(&source, "https://example.test/mcp").unwrap()["x-api-key"],
            "host-secret"
        );
        assert!(headers(&source, "https://changed.test/mcp").is_err());
        assert!(preview("relative.json").is_err());
        assert_eq!(
            serde_json::from_slice::<Value>(&std::fs::read(&path).unwrap()).unwrap(),
            root,
            "import never mutates Cline"
        );
        std::fs::remove_dir_all(dir).unwrap();
    }
}

//! MCP forwarding: the broker is an MCP server toward containers and an
//! MCP client toward upstream. Terminates, never tunnels: the container
//! session is answered locally, only tools/list and tools/call are
//! reconstructed upstream, and the bearer token (from a host env var)
//! never enters the container. One resolver (`Forward::allows`) computes
//! both the filtered tools/list and each tools/call verdict.

use std::{collections::HashMap, path::Path, sync::Arc};

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use tokio::sync::Mutex;

use crate::state::{AppState, Verdict};

pub const PROTOCOL_VERSION: &str = "2025-03-26";

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ForwardConfig {
    /// Path segment containers address: POST /mcp/{name}.
    pub name: String,
    /// Upstream streamable-HTTP endpoint, e.g. https://mcp.linear.app/mcp
    pub url: String,
    /// Host env var holding the bearer token (API key or OAuth token).
    #[serde(default)]
    pub bearer_env: String,
    /// OAuth scope to request, e.g. "read" for Linear read-only.
    #[serde(default)]
    pub scope: Option<String>,
    /// Tool allowlist; list-filtering and call-checking share it.
    pub tools: Vec<String>,
    /// None preserves legacy all-approved-guests behavior; [] denies all.
    #[serde(default)]
    pub guests: Option<Vec<String>>,
    /// Read-only link to a host Cline server; credentials are never copied.
    #[serde(default)]
    pub cline: Option<crate::mcp_import::ClineSource>,
    /// Explicit broker-owned OAuth. Cline is provenance only in this mode;
    /// its credentials are never read or used as fallback.
    #[serde(default)]
    pub oauth: bool,
}

pub fn validate_configs(configs: &[ForwardConfig]) -> Result<()> {
    let mut names = std::collections::HashSet::new();
    for config in configs {
        if config.name.is_empty()
            || !config
                .name
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b"-_".contains(&b))
        {
            anyhow::bail!("forward names must contain only letters, digits, '-' or '_'");
        }
        if !names.insert(&config.name) {
            anyhow::bail!("duplicate MCP forward '{}'", config.name);
        }
        let url = reqwest::Url::parse(&config.url).context("invalid MCP URL")?;
        if !matches!(url.scheme(), "http" | "https")
            || url.host_str().is_none()
            || !url.username().is_empty()
            || url.password().is_some()
            || url.fragment().is_some()
        {
            anyhow::bail!("MCP URL must be HTTP(S) without embedded credentials or fragment");
        }
        if config.tools.iter().any(|t| t.is_empty())
            || config
                .guests
                .as_ref()
                .is_some_and(|g| g.iter().any(|n| n.is_empty()))
        {
            anyhow::bail!("tool and guest names must not be empty");
        }
        if let Some(source) = &config.cline {
            if !Path::new(&source.path).is_absolute() || source.server.is_empty() {
                anyhow::bail!("Cline link requires an absolute host path and server name");
            }
            if !config.oauth && (!config.bearer_env.is_empty() || config.scope.is_some()) {
                anyhow::bail!(
                    "Cline-linked authentication is owned by Cline; do not also set bearer_env or scope"
                );
            }
        }
    }
    Ok(())
}

/// Where MCP forwards are configured, for display to the user.
pub fn forwards_path(data_dir: &Path) -> std::path::PathBuf {
    data_dir.join("mcp-forwards.json")
}

/// Loads mcp-forwards.json from the data dir; absent file means none.
pub fn load_forwards(data_dir: &Path) -> Result<Vec<ForwardConfig>> {
    let path = forwards_path(data_dir);
    if !path.exists() {
        return Ok(Vec::new());
    }
    let text =
        std::fs::read_to_string(&path).with_context(|| format!("read {}", path.display()))?;
    serde_json::from_str(&text).with_context(|| format!("parse {}", path.display()))
}

pub struct Forward {
    config: ForwardConfig,
    settings: crate::settings::Settings,
    /// Upstream Mcp-Session-Id once initialized.
    session: Arc<Mutex<Option<(uuid::Uuid, String)>>>,
    client: reqwest::Client,
    pub oauth_session: Arc<crate::mcp_oauth::Session>,
}

impl Forward {
    pub fn new(config: ForwardConfig, settings: crate::settings::Settings) -> Self {
        let oauth_session = Arc::new(crate::mcp_oauth::Session::new(
            config.name.clone(),
            config.url.clone(),
            settings.clone(),
        ));
        Self {
            config,
            settings,
            session: Arc::new(Mutex::new(None)),
            // Never send imported credentials to a redirect destination.
            client: reqwest::Client::builder()
                .redirect(reqwest::redirect::Policy::none())
                .build()
                .expect("MCP HTTP client"),
            oauth_session,
        }
    }

    /// The single policy resolver: tools/list filtering and tools/call
    /// authorization both call this, so they cannot diverge.
    pub fn allows(&self, tool: &str) -> bool {
        self.config.tools.iter().any(|t| t == tool)
    }

    pub fn allows_guest(&self, guest: &str) -> bool {
        self.config
            .guests
            .as_ref()
            .is_none_or(|guests| guests.iter().any(|g| g == guest))
    }

    fn same_upstream(&self, config: &ForwardConfig) -> bool {
        self.config.url == config.url
            && self.config.bearer_env == config.bearer_env
            && self.config.scope == config.scope
            && self.config.cline == config.cline
            && self.config.oauth == config.oauth
    }

    async fn authenticate(
        &self,
        mut request: reqwest::RequestBuilder,
    ) -> Result<(reqwest::RequestBuilder, Option<String>)> {
        if self.config.oauth {
            let token = [REDACTED];
            return Ok((request.bearer_auth(&token), Some(token)));
        } else if let Some(source) = &self.config.cline {
            for (name, value) in crate::mcp_import::headers(source, &self.config.url)? {
                request = request.header(name, value);
            }
        } else if !self.config.bearer_env.is_empty()
            || self
                .settings
                .secret(&format!("mcp:{}", self.config.name))
                .is_some()
        {
            request = request.bearer_auth(self.bearer().await?);
        }
        Ok((request, None))
    }

    /// Removes disallowed tools from an upstream tools/list result.
    pub fn filter_list_result(&self, result: &mut Value) {
        if let Some(tools) = result.get_mut("tools").and_then(Value::as_array_mut) {
            tools.retain(|tool| {
                tool.get("name")
                    .and_then(Value::as_str)
                    .is_some_and(|name| self.allows(name))
            });
        }
    }

    /// Legacy static credential resolution; broker OAuth never falls back
    /// to these values or imported Cline credentials after disconnect.
    async fn bearer(&self) -> Result<String> {
        if let Some(token) = self.settings.secret(&format!("mcp:{}", self.config.name)) {
            return Ok(token);
        }
        std::env::var(&self.config.bearer_env).with_context(|| {
            format!(
                "MCP forward '{}': no OAuth session, stored token, or env var {} (connect it in settings)",
                self.config.name, self.config.bearer_env
            )
        })
    }
}

impl Forward {
    /// Sends one JSON-RPC message upstream, initializing the session on
    /// first use. Returns the parsed JSON-RPC response.
    pub async fn call_upstream(&self, message: Value) -> Result<Value> {
        let mut session = self.session.lock().await;
        let generation = self.oauth_session.connection_epoch();
        if session
            .as_ref()
            .is_none_or(|(epoch, _)| *epoch != generation)
        {
            *session = Some((generation, self.initialize_upstream().await?));
        }
        let (_, session_id) = session.clone().expect("session just initialized");
        drop(session);
        self.post(message, Some(&session_id)).await
    }

    async fn initialize_upstream(&self) -> Result<String> {
        let init = json!({
            "jsonrpc": "2.0",
            "id": "fz-init",
            "method": "initialize",
            "params": {
                "protocolVersion": PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": {"name": "friendzone-broker", "version": env!("CARGO_PKG_VERSION")}
            }
        });
        let response = self
            .post_raw(init, None)
            .await
            .context("upstream initialize")?;
        let session_id = response
            .headers()
            .get("mcp-session-id")
            .and_then(|v| v.to_str().ok())
            .unwrap_or_default()
            .to_owned();
        let initialized_result = parse_body(response).await.context("initialize response")?;
        if initialized_result.get("error").is_some() || initialized_result.get("result").is_none() {
            anyhow::bail!("upstream rejected MCP initialization");
        }
        let initialized = json!({"jsonrpc": "2.0", "method": "notifications/initialized"});
        self.post_raw(initialized, Some(&session_id))
            .await
            .context("upstream initialized notification")?
            .error_for_status()
            .context("upstream rejected initialized notification")?;
        Ok(session_id)
    }

    async fn post(&self, message: Value, session_id: Option<&str>) -> Result<Value> {
        let response = self.post_raw(message, session_id).await?;
        parse_body(response).await
    }

    async fn post_raw(
        &self,
        message: Value,
        session_id: Option<&str>,
    ) -> Result<reqwest::Response> {
        let (response, sent_token) = self.post_once(&message, session_id, None).await?;
        // Expired-token 401: refresh once and retry, so agents never
        // see a reauth seam.
        if response.status() == reqwest::StatusCode::UNAUTHORIZED
            && let Some(sent_token) = sent_token
        {
            let token = [REDACTED];
            return Ok(self.post_once(&message, session_id, Some(token)).await?.0);
        }
        Ok(response)
    }

    async fn post_once(
        &self,
        message: &Value,
        session_id: Option<&str>,
        bearer: Option<String>,
    ) -> Result<(reqwest::Response, Option<String>)> {
        let mut request = self
            .client
            .post(&self.config.url)
            .header("Accept", "application/json, text/event-stream")
            .header("MCP-Protocol-Version", PROTOCOL_VERSION)
            .json(message);
        let (authenticated, sent_token) = match bearer {
            Some(token) => (request.bearer_auth(&token), Some(token)),
            None => self.authenticate(request).await?,
        };
        request = authenticated;
        if let Some(id) = session_id.filter(|id| !id.is_empty()) {
            request = request.header("Mcp-Session-Id", id);
        }
        Ok((
            request.send().await.context("upstream MCP request")?,
            sent_token,
        ))
    }
}

/// Streamable HTTP responses are plain JSON or an SSE stream whose final
/// data line carries the JSON-RPC response.
async fn parse_body(response: reqwest::Response) -> Result<Value> {
    let content_type = response
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or_default()
        .to_owned();
    let status = response.status();
    let text = response.text().await.context("read upstream body")?;
    if !status.is_success() {
        // Upstreams may echo credentials in errors; never expose bodies
        // to the guest or host UI. Cline-linked sessions refresh in Cline.
        anyhow::bail!(
            "upstream returned {status}; authorize this forward in the host Friendzone UI, not in the guest"
        );
    }
    if content_type.starts_with("text/event-stream") {
        let last = text
            .lines()
            .filter_map(|line| line.strip_prefix("data:"))
            .filter_map(|data| serde_json::from_str::<Value>(data.trim()).ok())
            .next_back();
        last.context("no JSON-RPC message in SSE response")
    } else if text.is_empty() {
        Ok(Value::Null)
    } else {
        serde_json::from_str(&text).context("parse upstream JSON")
    }
}

/// Shared, reloadable set of forwards: the UI edits the file and calls
/// reload; the MCP endpoint reads through it per message.
#[derive(Clone)]
pub struct ForwardRegistry {
    data_dir: std::path::PathBuf,
    settings: crate::settings::Settings,
    forwards: Arc<std::sync::RwLock<HashMap<String, Arc<Forward>>>>,
    update: Arc<std::sync::Mutex<()>>,
}

impl ForwardRegistry {
    pub fn load(data_dir: &Path, settings: crate::settings::Settings) -> Result<Self> {
        let registry = Self {
            data_dir: data_dir.to_owned(),
            settings,
            forwards: Arc::new(std::sync::RwLock::new(HashMap::new())),
            update: Arc::new(std::sync::Mutex::new(())),
        };
        registry.reload()?;
        Ok(registry)
    }

    /// Re-read and validate before publishing. Unchanged upstreams keep
    /// their sessions, including when only tool/guest permissions change.
    pub fn reload(&self) -> Result<usize> {
        let _update = self.update.lock().expect("registry update lock");
        let configs = load_forwards(&self.data_dir)?;
        validate_configs(&configs)?;
        self.publish(configs)
    }

    pub fn save(&self, configs: Vec<ForwardConfig>) -> Result<usize> {
        validate_configs(&configs)?;
        let _update = self.update.lock().expect("registry update lock");
        // Persistence and publication share one writer boundary. New
        // messages see the new snapshot; in-flight Arc holders finish.
        crate::storage::atomic_write(&self.config_path(), &serde_json::to_vec_pretty(&configs)?)?;
        self.publish(configs)
    }

    fn publish(&self, configs: Vec<ForwardConfig>) -> Result<usize> {
        let mut current = self.forwards.write().expect("forwards lock");
        let rebuilt: HashMap<String, Arc<Forward>> = configs
            .into_iter()
            .map(|config| {
                if let Some(old) = current.get(&config.name) {
                    if old.config == config {
                        return (config.name.clone(), old.clone());
                    }
                    if old.same_upstream(&config) {
                        return (
                            config.name.clone(),
                            Arc::new(Forward {
                                config,
                                settings: self.settings.clone(),
                                session: old.session.clone(),
                                client: old.client.clone(),
                                oauth_session: old.oauth_session.clone(),
                            }),
                        );
                    }
                }
                (
                    config.name.clone(),
                    Arc::new(Forward::new(config, self.settings.clone())),
                )
            })
            .collect();
        let count = rebuilt.len();
        for (name, old) in current.iter() {
            if rebuilt
                .get(name)
                .is_none_or(|new| !Arc::ptr_eq(&old.oauth_session, &new.oauth_session))
            {
                old.oauth_session.retire()?;
            }
        }
        *current = rebuilt;
        Ok(count)
    }

    pub fn get(&self, name: &str) -> Option<Arc<Forward>> {
        self.forwards
            .read()
            .expect("forwards lock")
            .get(name)
            .cloned()
    }

    pub fn enable_oauth(&self, name: &str, scope: Option<String>) -> Result<Arc<Forward>> {
        let _update = self.update.lock().expect("registry update lock");
        let mut configs = self.configs();
        let config = configs
            .iter_mut()
            .find(|config| config.name == name)
            .context("unknown MCP forward")?;
        config.oauth = true;
        config.bearer_env.clear();
        config.scope = scope;
        validate_configs(&configs)?;
        crate::storage::atomic_write(&self.config_path(), &serde_json::to_vec_pretty(&configs)?)?;
        self.publish(configs)?;
        self.get(name).context("forward disappeared")
    }

    pub fn validation_forward(&self, config: ForwardConfig) -> Result<Arc<Forward>> {
        validate_configs(std::slice::from_ref(&config))?;
        if config.oauth {
            // Validation and guest calls must share the refresh lock and
            // lifecycle. Never construct a second OAuth owner for one name.
            return self
                .get(&config.name)
                .filter(|forward| forward.config.oauth && forward.config.url == config.url)
                .context(
                    "Save this forward for OAuth and authorize it in Friendzone before validation",
                );
        }
        Ok(Arc::new(Forward::new(config, self.settings.clone())))
    }

    pub fn configs(&self) -> Vec<ForwardConfig> {
        let mut configs: Vec<ForwardConfig> = self
            .forwards
            .read()
            .expect("forwards lock")
            .values()
            .map(|forward| forward.config.clone())
            .collect();
        configs.sort_by(|a, b| a.name.cmp(&b.name));
        configs
    }

    pub fn config_path(&self) -> std::path::PathBuf {
        forwards_path(&self.data_dir)
    }
}

#[derive(Clone)]
pub struct McpState {
    pub app: AppState,
    pub registry: ForwardRegistry,
}

impl McpState {
    pub fn new(app: AppState, registry: ForwardRegistry) -> Self {
        Self { app, registry }
    }
}

/// Handles one container-side JSON-RPC message for the named forward.
/// The container session is terminated here: initialize is answered
/// locally, only tools/list and tools/call are reconstructed upstream.
pub async fn handle_message(
    state: &McpState,
    name: &str,
    container: &str,
    peer: std::net::IpAddr,
    message: Value,
) -> Value {
    let id = message.get("id").cloned().unwrap_or(Value::Null);
    let method = message
        .get("method")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_owned();
    let Some(forward) = state.registry.get(name) else {
        return error_response(id, -32601, &format!("unknown MCP forward '{name}'"));
    };
    let denial = if state.app.is_killed(container) {
        Some("container is killed")
    } else if state.app.authorize(container, peer) != crate::state::Authorization::Allowed {
        Some("container is not approved for this address; check approval and IP pin in the host UI")
    } else if !forward.allows_guest(container) {
        Some("MCP forward is not shared with this guest")
    } else {
        None
    };
    if let Some(reason) = denial {
        let event = state.app.record(
            container.into(),
            format!("MCP {method}"),
            format!("mcp:{name}"),
            Verdict::Blocked,
        );
        state.app.annotate(event, None, Some(reason.into()));
        return error_response(id, -32000, reason);
    }
    let (verdict, response) = dispatch(&forward, &method, id, &message).await;
    let event = state.app.record(
        container.to_owned(),
        format!("MCP {method}"),
        format!("mcp:{name}"),
        verdict,
    );
    if let Some(reason) = response.pointer("/error/message").and_then(Value::as_str) {
        state.app.annotate(event, None, Some(reason.into()));
    }
    response
}

async fn dispatch(forward: &Forward, method: &str, id: Value, message: &Value) -> (Verdict, Value) {
    match method {
        "initialize" => (
            Verdict::Allowed,
            json!({
                "jsonrpc": "2.0",
                "id": id,
                "result": {
                    "protocolVersion": PROTOCOL_VERSION,
                    "capabilities": {"tools": {}},
                    "serverInfo": {"name": "friendzone", "version": env!("CARGO_PKG_VERSION")}
                }
            }),
        ),
        "notifications/initialized" | "notifications/cancelled" => (Verdict::Allowed, Value::Null),
        "ping" => (
            Verdict::Allowed,
            json!({"jsonrpc": "2.0", "id": id, "result": {}}),
        ),
        "tools/list" => match forward.call_upstream(message.clone()).await {
            Ok(mut response) => {
                if let Some(result) = response.get_mut("result") {
                    forward.filter_list_result(result);
                }
                (Verdict::Allowed, response)
            }
            Err(error) => (
                Verdict::Blocked,
                error_response(id, -32603, &format!("upstream: {error:#}")),
            ),
        },
        "tools/call" => {
            let tool = message
                .pointer("/params/name")
                .and_then(Value::as_str)
                .unwrap_or_default();
            if !forward.allows(tool) {
                return (
                    Verdict::Blocked,
                    error_response(id, -32602, &format!("tool '{tool}' is not forwarded")),
                );
            }
            match forward.call_upstream(message.clone()).await {
                Ok(response) => (Verdict::Allowed, response),
                Err(error) => (
                    Verdict::Blocked,
                    error_response(id, -32603, &format!("upstream: {error:#}")),
                ),
            }
        }
        other => (
            Verdict::Blocked,
            error_response(id, -32601, &format!("method '{other}' is not forwarded")),
        ),
    }
}

fn error_response(id: Value, code: i64, message: &str) -> Value {
    json!({
        "jsonrpc": "2.0",
        "id": id,
        "error": {"code": code, "message": message}
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn live_policy_updates_preserve_sessions_and_reject_invalid_config() {
        let dir = std::env::temp_dir().join(format!("fz-live-mcp-{}", uuid::Uuid::new_v4()));
        let settings = crate::settings::Settings::load(&dir).unwrap();
        let registry = ForwardRegistry::load(&dir, settings).unwrap();
        let mut config = linear_forward().config;
        config.guests = Some(vec!["guest".into()]);
        registry.save(vec![config.clone()]).unwrap();
        let before = registry.get("linear").unwrap();
        *before.session.lock().await =
            Some((before.oauth_session.connection_epoch(), "session-1".into()));
        registry.reload().unwrap();
        assert!(Arc::ptr_eq(&before, &registry.get("linear").unwrap()));
        let app = AppState::default();
        let ip = "127.0.0.1".parse().unwrap();
        app.authorize("guest", ip);
        app.approve_container("guest", true).unwrap();
        let state = McpState::new(app, registry.clone());
        let init = json!({"jsonrpc":"2.0", "id":1, "method":"initialize"});
        assert!(
            handle_message(&state, "linear", "guest", ip, init.clone())
                .await
                .get("result")
                .is_some()
        );
        assert!(
            handle_message(
                &state,
                "linear",
                "guest",
                "127.0.0.2".parse().unwrap(),
                init.clone()
            )
            .await
            .get("error")
            .is_some()
        );
        config.guests = Some(vec![]);
        config.tools = vec![];
        registry.save(vec![config.clone()]).unwrap();
        let after = registry.get("linear").unwrap();
        assert!(Arc::ptr_eq(&before.session, &after.session));
        assert!(
            before.allows("get_issue"),
            "in-flight snapshot retains its policy"
        );
        assert!(!after.allows("get_issue"), "new snapshot uses new policy");
        assert!(
            handle_message(&state, "linear", "guest", ip, init.clone())
                .await
                .get("error")
                .is_some()
        );
        let saved = std::fs::read(registry.config_path()).unwrap();
        assert!(registry.save(vec![config.clone(), config.clone()]).is_err());
        assert_eq!(std::fs::read(registry.config_path()).unwrap(), saved);
        std::fs::write(registry.config_path(), b"[").unwrap();
        assert!(registry.reload().is_err());
        assert!(Arc::ptr_eq(&after, &registry.get("linear").unwrap()));
        registry.save(vec![]).unwrap();
        assert!(registry.get("linear").is_none());
        assert!(
            handle_message(&state, "linear", "guest", ip, init)
                .await
                .get("error")
                .is_some()
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[tokio::test]
    async fn cline_link_uses_current_credentials_through_real_mcp_path() {
        use axum::{Json, Router, http::HeaderMap, routing::post};
        let seen = Arc::new(std::sync::Mutex::new(Vec::new()));
        let calls = seen.clone();
        let app = Router::new().route("/mcp", post(move |headers: HeaderMap, Json(message): Json<Value>| {
            let calls = calls.clone();
            async move {
                calls.lock().unwrap().push((message["method"].as_str().unwrap().to_owned(), headers["authorization"].to_str().unwrap().to_owned()));
                let result = match message["method"].as_str().unwrap() {
                    "initialize" => json!({"protocolVersion":PROTOCOL_VERSION, "capabilities":{"tools":{}}, "serverInfo":{"name":"test", "version":"1"}}),
                    "tools/list" => json!({"tools":[{"name":"read"}, {"name":"write"}]}),
                    _ => json!({}),
                };
                Json(json!({"jsonrpc":"2.0", "id":message["id"], "result":result}))
            }
        }));
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let url = format!("http://{}/mcp", listener.local_addr().unwrap());
        let server = tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
        let dir = std::env::temp_dir().join(format!("fz-linked-mcp-{}", uuid::Uuid::new_v4()));
        let settings = crate::settings::Settings::load(&dir).unwrap();
        let path = dir.join("cline_mcp_settings.json");
        let write_token = |token: &str| {
            std::fs::write(&path, serde_json::to_vec(&json!({"mcpServers":{"test":{"transport":{"type":"streamableHttp", "url":url}, "oauth":{"tokens":{"access_token":token, "refresh_token":"never-copy"}}}}})).unwrap()).unwrap()
        };
        write_token("first");
        let registry = ForwardRegistry::load(&dir, settings).unwrap();
        registry
            .save(vec![ForwardConfig {
                name: "test".into(),
                url: url.clone(),
                bearer_env: String::new(),
                scope: None,
                tools: vec!["read".into()],
                guests: Some(vec!["guest".into()]),
                cline: Some(crate::mcp_import::ClineSource {
                    path: path.to_str().unwrap().into(),
                    server: "test".into(),
                }),
                oauth: false,
            }])
            .unwrap();
        let app = AppState::default();
        app.add_container("guest", None).unwrap();
        let state = McpState::new(app, registry);
        let list = json!({"jsonrpc":"2.0", "id":1, "method":"tools/list"});
        let response = handle_message(
            &state,
            "test",
            "guest",
            "127.0.0.1".parse().unwrap(),
            list.clone(),
        )
        .await;
        assert_eq!(response["result"]["tools"], json!([{"name":"read"}]));
        write_token("rotated-by-cline");
        handle_message(&state, "test", "guest", "127.0.0.1".parse().unwrap(), list).await;
        let rejected = handle_message(
            &state,
            "test",
            "guest",
            "127.0.0.1".parse().unwrap(),
            json!({"jsonrpc":"2.0", "id":2, "method":"tools/call", "params":{"name":"write"}}),
        )
        .await;
        assert!(rejected.get("error").is_some());
        let calls = seen.lock().unwrap();
        assert_eq!(
            calls
                .iter()
                .filter(|(method, _)| method == "initialize")
                .count(),
            1
        );
        assert_eq!(
            calls.last().unwrap(),
            &("tools/list".into(), "Bearer rotated-by-cline".into())
        );
        assert!(
            !std::fs::read_to_string(state.registry.config_path())
                .unwrap()
                .contains("never-copy")
        );
        drop(calls);
        server.abort();
        std::fs::remove_dir_all(dir).unwrap();
    }

    fn linear_forward() -> Forward {
        let dir = std::env::temp_dir().join(format!("fz-mcp-{}", uuid::Uuid::new_v4()));
        let settings = crate::settings::Settings::load(&dir).unwrap();
        Forward::new(
            ForwardConfig {
                name: "linear".into(),
                url: "https://mcp.example.test/mcp".into(),
                bearer_env: "FZ_TEST_UNSET".into(),
                scope: None,
                tools: vec!["list_issues".into(), "get_issue".into()],
                guests: None,
                cline: None,
                oauth: false,
            },
            settings,
        )
    }

    #[test]
    fn one_resolver_filters_list_and_gates_calls() {
        let forward = linear_forward();
        // Same resolver: what filter removes, allows() rejects.
        let mut result = json!({"tools": [
            {"name": "list_issues"},
            {"name": "create_issue"},
        ]});
        forward.filter_list_result(&mut result);
        let listed: Vec<&str> = result["tools"]
            .as_array()
            .unwrap()
            .iter()
            .map(|t| t["name"].as_str().unwrap())
            .collect();
        assert_eq!(listed, ["list_issues"]);
        assert!(forward.allows("list_issues"));
        assert!(!forward.allows("create_issue"));
    }

    #[tokio::test]
    async fn disallowed_tool_call_is_rejected_before_upstream() {
        // bearer_env is unset and the URL unroutable: reaching upstream
        // would fail loudly, proving rejection happens first.
        let forward = linear_forward();
        let message = json!({
            "jsonrpc": "2.0", "id": 1, "method": "tools/call",
            "params": {"name": "create_issue", "arguments": {}}
        });
        let (verdict, response) = dispatch(&forward, "tools/call", json!(1), &message).await;
        assert!(matches!(verdict, Verdict::Blocked));
        assert!(
            response["error"]["message"]
                .as_str()
                .unwrap()
                .contains("not forwarded")
        );
    }

    #[tokio::test]
    async fn unknown_methods_are_not_forwarded() {
        let forward = linear_forward();
        let message = json!({"jsonrpc": "2.0", "id": 2, "method": "resources/list"});
        let (verdict, response) = dispatch(&forward, "resources/list", json!(2), &message).await;
        assert!(matches!(verdict, Verdict::Blocked));
        assert_eq!(response["error"]["code"], -32601);
    }

    #[tokio::test]
    async fn initialize_is_answered_locally() {
        let forward = linear_forward();
        let message = json!({"jsonrpc": "2.0", "id": 3, "method": "initialize", "params": {}});
        let (verdict, response) = dispatch(&forward, "initialize", json!(3), &message).await;
        assert!(matches!(verdict, Verdict::Allowed));
        assert_eq!(response["result"]["serverInfo"]["name"], "friendzone");
    }
}

use std::{fs, io::Write, path::Path};

use anyhow::{Context, Result};

/// Publish a complete file, never a partially written configuration.
/// Callers serialize concurrent writers and publish in-memory state only
/// after this succeeds. Staging beside the destination keeps rename local.
pub fn atomic_write(path: &Path, contents: &[u8]) -> Result<()> {
    let temporary = path.with_extension(format!("{}.tmp", uuid::Uuid::new_v4()));
    let result = (|| {
        let mut options = fs::OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            options.mode(0o600);
        }
        let mut file = options.open(&temporary)?;
        file.write_all(contents)?;
        file.sync_all()?;
        drop(file);
        fs::rename(&temporary, path)
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result.with_context(|| format!("write {} atomically", path.display()))
}

use std::{net::SocketAddr, process::Output, time::Duration};

use axum::{Router, http::StatusCode, routing::get};
use tokio::{net::TcpListener, process::Command, task::JoinHandle};

struct TestServer {
    address: SocketAddr,
    task: JoinHandle<()>,
}

impl TestServer {
    async fn start(app: Router) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let task = tokio::spawn(async move {
            axum::serve(listener, app).await.unwrap();
        });
        Self { address, task }
    }

    fn url(&self) -> String {
        format!("http://{}", self.address)
    }

    fn proxy_url(&self) -> String {
        format!("http://{}", self.address)
    }
}

impl Drop for TestServer {
    fn drop(&mut self) {
        self.task.abort();
    }
}

async fn denying_proxy() -> TestServer {
    TestServer::start(Router::new().fallback(|| async {
        (
            StatusCode::FORBIDDEN,
            "friendzone: container awaiting approval; use Approve + pin IP in the UI inbox",
        )
    }))
    .await
}

async fn run_fz(proxy: &TestServer, args: &[&str]) -> Output {
    let mut command = Command::new(env!("CARGO_BIN_EXE_fz"));
    command.args(args).kill_on_drop(true);
    // Model a sourced guest env, without mutating the test runner's
    // environment (other tests and Tokio threads run concurrently).
    for name in [
        "HTTP_PROXY",
        "http_proxy",
        "HTTPS_PROXY",
        "https_proxy",
        "ALL_PROXY",
        "all_proxy",
    ] {
        command.env(name, proxy.proxy_url());
    }
    command.env("NO_PROXY", "").env("no_proxy", "");
    for name in ["REQUEST_METHOD", "SUDO_USER", "SUDO_UID", "SUDO_GID"] {
        command.env_remove(name);
    }
    tokio::time::timeout(Duration::from_secs(20), command.output())
        .await
        .expect("fz command timed out")
        .expect("run fz command")
}

fn output_text(output: &Output) -> String {
    format!(
        "stdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr),
    )
}

#[tokio::test]
async fn doctor_checks_broker_directly_with_proxy_env_set() {
    let broker = TestServer::start(Router::new().route("/health", get(|| async { "ok" }))).await;
    let proxy = denying_proxy().await;
    let output = run_fz(
        &proxy,
        &[
            "doctor",
            "--broker",
            &broker.url(),
            "--proxy",
            &proxy.proxy_url(),
        ],
    )
    .await;
    let text = output_text(&output);
    assert!(output.status.success(), "{text}");
    assert!(text.contains("[PASS] broker reachable"), "{text}");
    assert!(text.contains("TCP only"), "{text}");
    assert!(
        text.contains("container approval and proxy forwarding are not tested yet"),
        "{text}"
    );
}

#[tokio::test]
async fn doctor_still_reports_broker_http_errors() {
    let broker = TestServer::start(
        Router::new().route("/health", get(|| async { StatusCode::SERVICE_UNAVAILABLE })),
    )
    .await;
    let proxy = denying_proxy().await;
    let output = run_fz(
        &proxy,
        &[
            "doctor",
            "--broker",
            &broker.url(),
            "--proxy",
            &proxy.proxy_url(),
        ],
    )
    .await;
    let text = output_text(&output);
    assert!(!output.status.success(), "{text}");
    assert!(text.contains("[FAIL] broker reachable"), "{text}");
    assert!(text.contains("503 Service Unavailable"), "{text}");
}

#[tokio::test]
async fn obsolete_setup_command_is_not_a_second_installation_path() {
    let proxy = denying_proxy().await;
    let output = run_fz(&proxy, &["setup"]).await;
    assert!(!output.status.success());
    assert!(output_text(&output).contains("unrecognized subcommand"));
}

