// Friendzone traced-command supervisor v1.
'use strict';

const path = require('node:path');
const { spawn } = require('node:child_process');
const { context, propagation, trace, SpanStatusCode } = require('@opentelemetry/api');

const telemetry = require(process.env.FZ_TRACE_PRELOAD);
const argv = process.argv.slice(2);
const command = argv.shift();
if (!command) {
  console.error('Friendzone trace supervisor requires a command.');
  process.exit(2);
}

const commandName = path.basename(command);
const span = trace.getTracer('friendzone-traced-command').startSpan('friendzone.command', {
  attributes: {
    'process.executable.name': commandName,
  },
});
const commandContext = trace.setSpan(context.active(), span);
const carrier = {};
propagation.inject(commandContext, carrier);
const childEnv = {
  ...process.env,
  FZ_TRACEPARENT: carrier.traceparent,
};
delete childEnv.FZ_TRACE_PRELOAD;
delete childEnv.FZ_TRACE_SUPERVISOR;
if (carrier.tracestate) childEnv.FZ_TRACESTATE = carrier.tracestate;
else delete childEnv.FZ_TRACESTATE;

let finished = false;
let child;
const signals = ['SIGHUP', 'SIGINT', 'SIGTERM'];
for (const signal of signals) {
  process.on(signal, () => {
    if (child && child.exitCode === null && child.signalCode === null) child.kill(signal);
  });
}

async function finish(code, signal, spawnError) {
  if (finished) return;
  finished = true;
  if (Number.isInteger(code)) span.setAttribute('process.exit.code', code);
  if (signal) span.setAttribute('process.exit.signal', signal);
  if (spawnError) span.setAttribute('error.type', spawnError.code || 'spawn_error');
  if (spawnError || signal || code !== 0) {
    span.setStatus({ code: SpanStatusCode.ERROR });
  }
  span.end();
  await telemetry.shutdown();

  if (signal) {
    for (const name of signals) process.removeAllListeners(name);
    try {
      process.kill(process.pid, signal);
      return;
    } catch (_) {
      process.exit(1);
    }
  }
  process.exit(Number.isInteger(code) ? code : 1);
}

try {
  child = context.with(commandContext, () => spawn(command, argv, {
    cwd: process.cwd(),
    env: childEnv,
    shell: false,
    stdio: 'inherit',
  }));
  child.once('error', error => {
    console.error(`Friendzone could not start ${commandName}: ${error.code || 'spawn error'}`);
    void finish(127, null, error);
  });
  child.once('close', (code, signal) => void finish(code, signal, null));
} catch (error) {
  console.error(`Friendzone could not start ${commandName}: ${error.code || 'spawn error'}`);
  void finish(127, null, error);
}

// Friendzone timeout tracing preload v1.
'use strict';

const {
  AlwaysOnSampler,
  BatchSpanProcessor,
  NodeTracerProvider,
} = require('@opentelemetry/sdk-trace-node');
const { ROOT_CONTEXT, context, propagation, trace } = require('@opentelemetry/api');
const { AsyncLocalStorageContextManager } = require('@opentelemetry/context-async-hooks');
const { OTLPTraceExporter } = require('@opentelemetry/exporter-trace-otlp-proto');
const { registerInstrumentations } = require('@opentelemetry/instrumentation');
const { HttpInstrumentation } = require('@opentelemetry/instrumentation-http');
const { UndiciInstrumentation } = require('@opentelemetry/instrumentation-undici');
const { resourceFromAttributes } = require('@opentelemetry/resources');

const provider = new NodeTracerProvider({
  resource: resourceFromAttributes({
    'service.name': process.env.OTEL_SERVICE_NAME || 'cline-guest',
  }),
  sampler: new AlwaysOnSampler(),
  spanProcessors: [new BatchSpanProcessor(new OTLPTraceExporter())],
});
const contextManager = new AsyncLocalStorageContextManager().enable();
provider.register({ contextManager });

// A traced-command supervisor passes its command span through this private
// carrier. Attach it before the wrapped program is loaded so later HTTP and
// Undici calls continue the same trace. Keep the variables for Node descendants.
const inheritedCarrier = {
  traceparent: process.env.FZ_TRACEPARENT,
  tracestate: process.env.FZ_TRACESTATE,
};
const inherited = propagation.extract(ROOT_CONTEXT, inheritedCarrier);
if (trace.getSpanContext(inherited)) contextManager.attach(inherited);

registerInstrumentations({
  instrumentations: [new HttpInstrumentation(), new UndiciInstrumentation()],
});

let shutdownPromise;
async function shutdown() {
  if (!shutdownPromise) shutdownPromise = provider.shutdown();
  try {
    await shutdownPromise;
  } catch (error) {
    console.error('Friendzone trace flush failed:', error);
  }
}
process.once('beforeExit', () => void shutdown());

module.exports = { shutdown };

function ConvertTo-FzCertificateIdentity([string]$Text) {
    $match=[regex]::Match($Text,'\A\s*-----BEGIN CERTIFICATE-----\s*(?<body>[A-Za-z0-9+/=\s]+?)\s*-----END CERTIFICATE-----\s*\z')
    if(-not $match.Success){throw 'Friendzone CA must contain exactly one PEM certificate'}
    try{$der=[Convert]::FromBase64String(($match.Groups['body'].Value -replace '\s',''))}catch{throw 'Friendzone CA contains invalid base64'}
    $certificate=New-Object Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList (,$der)
    try{
        $basic=$certificate.Extensions|Where-Object{$_.Oid.Value -eq '2.5.29.19'}|Select-Object -First 1
        if($null -eq $basic){throw 'Friendzone certificate is not a CA'}
        $constraints=New-Object Security.Cryptography.X509Certificates.X509BasicConstraintsExtension -ArgumentList $basic,$basic.Critical
        if(-not $constraints.CertificateAuthority){throw 'Friendzone certificate is not a CA'}
        if([DateTime]::UtcNow -lt $certificate.NotBefore.ToUniversalTime() -or [DateTime]::UtcNow -gt $certificate.NotAfter.ToUniversalTime()){throw 'Friendzone CA is not currently valid'}
        return @{thumbprint=$certificate.Thumbprint.ToUpperInvariant();der=[Convert]::ToBase64String($der)}
    }finally{$certificate.Dispose()}
}
function Get-FzTrustedCertificate([string]$Thumbprint, [ValidateSet('CurrentUser','LocalMachine')][string]$StoreLocation='CurrentUser') {
    $store=New-Object Security.Cryptography.X509Certificates.X509Store -ArgumentList 'Root',$StoreLocation
    try{
        $store.Open([Security.Cryptography.X509Certificates.OpenFlags]::ReadOnly)
        $matches=@($store.Certificates|Where-Object{$_.Thumbprint -ieq $Thumbprint})
        if($matches.Count -eq 0){return @{present=$false;der=$null}}
        $der=[Convert]::ToBase64String($matches[0].RawData)
        foreach($certificate in $matches){if([Convert]::ToBase64String($certificate.RawData)-cne$der){throw "Conflicting $StoreLocation root certificates have thumbprint $Thumbprint"}}
        return @{present=$true;der=$der}
    }finally{$store.Dispose()}
}
function Add-FzTrustedCertificate([string]$Der, [ValidateSet('CurrentUser','LocalMachine')][string]$StoreLocation='CurrentUser') {
    $certificate=New-Object Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList (,[Convert]::FromBase64String($Der))
    $store=New-Object Security.Cryptography.X509Certificates.X509Store -ArgumentList 'Root',$StoreLocation
    try{$store.Open([Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite);$store.Add($certificate)}finally{$store.Dispose();$certificate.Dispose()}
}
